SELECT /*selectMasterMpSoProgressList*/ A.BUYER_NAME, DECODE(STOCK_CNT,0,A.STATUS_TEXT,'*'||A.STATUS_TEXT) STATUS_TEXT, A.PO_NO, DECODE(A.BUYER,'KRDOOS0006',A.REF_IF_NO,A.LEGACY_PO_NO) LEGACY_PO_NO, A.AGENT_NAME, A.BUYER_ITEM_NO, A.REF_PR_NO, A.PO_DATE, A.RD_DATE, A.CD_DATE, DECODE(NVL(A.GR_DATE,NULL),NULL,'',A.GR_DATE) GR_DATE, DECODE(NVL(A.DS_DATE,NULL),NULL,'',A.DS_DATE) DS_DATE, DECODE(NVL(A.INVOICE_DATE,NULL),NULL,'',A.INVOICE_DATE) INVOICE_DATE, A.DELIVERY_ADD_DATE, A.DELIVERY_DATE, A.DESCRIPTION, A.SPECIFICATION, A.MAKER_NAME, A.UNIT_MEASURE, NVL(A.ITEM_QTY,0) AS PO_QTY, NVL(A.GR_QTY,0) AS GR_QTY1, NVL(A.INV_QTY,0) AS INV_QTY, NVL(A.DELIVERY_QTY,0) AS DELIVERY_QTY, NVL(A.UNIT_PRICE,0) AS UNIT_PRICE, (NVL(A.ITEM_AMT,0)) AS UNIT_SUM, NVL(A.AGENT_PRICE,0) AS AGENT_PRICE, (NVL(A.AGENT_ITEM_AMT,0)) AS AGENT_SUM, A.PO_DEPT_NAME, A.PO_USER_NAME, DECODE(#{st_non_masking_flag}, 'Y', A.PO_USER_NAME, F_GET_MASKING_RETURN(A.PO_USER_NAME, 'NAME')) AS PO_USER_NAME_MASK, A.REQ_DEPT_NAME, A.REQ_USER_NAME, DECODE(#{st_non_masking_flag}, 'Y', A.REQ_USER_NAME, F_GET_MASKING_RETURN(A.REQ_USER_NAME, 'NAME')) AS REQ_USER_NAME_MASK, A.PO_SEQ, A.LEGACY_PO_SEQ, A.AGENT_CODE, A.CONTRACT_NO, A.CONTRACT_SEQ, A.BUYER, A.BYIT_COMORG_CODE, A.PO_USER_ID, A.REQ_USER_ID, replace(replace(A.DS_REMARK,chr(10),''),chr(13),' ') as DS_REMARK, DECODE(NVL(A.INVOICE_DATE2,NULL),NULL,'',SUBSTR(A.INVOICE_DATE2,0,4)||'/'||SUBSTR(A.INVOICE_DATE2,5,2)||'/'||SUBSTR(A.INVOICE_DATE2,7,2)) INVOICE_DATE2, DECODE(NVL(A.DS_DATE2,NULL),NULL,'',SUBSTR(A.DS_DATE2,0,4)||'/'||SUBSTR(A.DS_DATE2,5,2)||'/'||SUBSTR(A.DS_DATE2,7,2)) DS_DATE2, DECODE(SCM_REMARK,NULL,'','SCM') AS SCM_REMARK, A.ADD_DATE, A.CANCEL_REMARK, NVL(A.GR_ITEM_AMT,0) AS GR_UNIT_SUM, NVL(A.AGENT_GR_ITEM_AMT,0) AS GR_AGENT_SUM, (SELECT IRS_NO FROM ICOMCMPY WHERE COM_CODE = A.AGENT_CODE) AS AGENT_IRS_NO, A.BUYER_CATEGORY_NO BUYER_CATEG_ID, A.BUYER_CATEG_NAME BUYER_CATEG_NAME, A.BUYER_CATEG_PATH BUYER_CATEG_PATH, A.CMS_CATEG_ID AS CMS_CATEG_ID, A.CATEG_PATH AS CATEG_PATH, A.REF_IF_NO AS REF_IF_NO, A.PO_REMARK AS PO_REMARK, A.PROCESS_TEXT AS PROCESS_TEXT, A.ORIGIN_AGENT AS ORIGIN_AGENT, A.ORIGIN_AGENT_NAME AS ORIGIN_AGENT_NAME, A.PO_REMARK_HD, DECODE(#{st_non_masking_flag}, 'Y', A.PO_REMARK_HD, F_GET_MASKING_RETURN(A.PO_REMARK_HD, 'REMARK')) AS PO_REMARK_HD_MASK, A.UNIT_TAX, A.LOG_TEXT, A.HA_DATE, A.WAREHOUSE_NAME, A.ACCOUNT_TYPE , A.PR_NO , A.PR_SEQ , (SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE A.BUYER = PRHD.BUYER AND A.PR_NO = PRHD.PR_NO AND ROWNUM =1 )CARD_USE_FLAG , (SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE A.BUYER = PRHD.BUYER AND A.PR_NO = PRHD.PR_NO AND ROWNUM =1 )CARD_CONFIRM_NO , A.IMAGE_KEY , DECODE(A.IMAGE_KEY,NULL,'2','3') IMAGE_KEY_YN , A.PO_IMAGE_KEY , DECODE(A.PO_IMAGE_KEY,NULL,'2','3') PO_IMAGE_KEY_YN , A.ST_DATE ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = A.ITEM_MAKE_TYPE) AS ITEM_MAKE_TYPE ,A.DOC_TYPE ,A.BUYER_DS_DATE ,A.SOUR_MNG ,A.MAKER_PART_NO ,F_GET_PLANT_MNG(A.BUYER ,A.PLANT ,'POMG' ,'NM') AS PLANT_USER_NM ,A.EXP_CUR ,A.EXP_CUR_PRICE ,A.EXP_FOR_UNIT_PRICE ,A.EXP_FOR_ITEM_AMT ,(SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M001' AND COD.CODE = A.ORIGIN_CODE) AS ORIGIN_TEXT , (SELECT DECODE(COUNT(*), 0, '', '이슈') FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ IN (A.PO_SEQ, '000000')) AS ISSUE ,A.CHANGE_USER_DEPT FROM ( SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = H.BUYER)) AS BUYER_NAME, MAX(D.PO_NO) PO_NO, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = H.AGENT)) AS AGENT_NAME, MAX(H.PO_CREATE_DATE) AS PO_DATE, MAX(D.RD_DATE) AS RD_DATE, (SELECT MAX(CD_DATE) FROM ICOMPORS WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS != 'D') CD_DATE, MAX(G.GR_DATE) AS GR_DATE, MAX(D.ITEM_QTY) AS ITEM_QTY, SUM(NVL(G.ITEM_QTY,0)) AS GR_QTY, MAX(D.UNIT_PRICE) AS UNIT_PRICE, MAX(D.ITEM_AMT) AS ITEM_AMT, MAX(D.AGENT_ITEM_AMT) AS AGENT_ITEM_AMT, MAX((SELECT C2.TEXT1 FROM ICOMCOD2 C2 WHERE C2.TYPE = 'C001' AND C2.COMPANY_CODE = D.BUYER AND C2.CODE = R.PURCHASER_DEPT)) AS PO_DEPT_NAME, MAX(DECODE(D.BUYER,'KRDOOD0001',R.ADD_USER_NAME,H.PURCHASER_NAME)) AS PO_USER_NAME, MAX(D.PO_SEQ) AS PO_SEQ, MAX(D.REF_PR_NO) AS REF_PR_NO, MAX(D.BUYER_ITEM_NO) AS BUYER_ITEM_NO, MAX(DECODE(D.PROCESS_TYPE,'0' ,(SELECT MIN(INVOICE_DATE) FROM ICOMIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <>'D') ,(SELECT MIN(INV_DATE) FROM WMSIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D'))) AS INVOICE_DATE, MAX(D.DS_DATE) AS DS_DATE, MAX(DECODE(D.PROCESS_TYPE,'0' ,(SELECT MIN(TO_CHAR(DELIVERY_ADD_DATE, 'YYYYMMDD')) FROM ICOMIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <>'D') ,(SELECT MIN(TO_CHAR(DELIVERY_ADD_DATE, 'YYYYMMDD')) FROM WMSIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D'))) AS DELIVERY_ADD_DATE, MAX(DECODE(D.PROCESS_TYPE,'0' ,(SELECT MIN(DELIVERY_DATE) FROM ICOMIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <>'D') ,(SELECT MIN(DELIVERY_DATE) FROM WMSIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D'))) AS DELIVERY_DATE, MAX(NVL(D.IV_QTY,0)) AS INV_QTY, MAX(NVL(D.DI_QTY,0)) AS DELIVERY_QTY, MAX(D.AGENT_PRICE) AS AGENT_PRICE, MAX((SELECT C2.TEXT1 FROM ICOMCOD2 C2 WHERE C2.TYPE = 'C001' AND C2.COMPANY_CODE = D.BUYER AND C2.CODE = R.REQ_DEPT)) AS REQ_DEPT_NAME, MAX((SELECT L.USER_NAME_LOC FROM ICOMLUSR L WHERE L.COM_CODE = D.BUYER AND L.USER_ID = R.REQ_USER_ID)) AS REQ_USER_NAME, MAX(D.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ, MAX(F_GET_PO_STTS(D.BUYER, D.PO_NO , D.PO_SEQ , 1)) AS STATUS_TEXT, MAX(D.DESCRIPTION) AS DESCRIPTION, MAX(D.SPECIFICATION) AS SPECIFICATION, MAX(D.MAKER_NAME) AS MAKER_NAME, MAX(D.UNIT_MEASURE) AS UNIT_MEASURE, MAX(D.LEGACY_PO_NO) AS LEGACY_PO_NO, MAX(D.BYIT_COMORG_CODE) AS BYIT_COMORG_CODE, MAX(H.AGENT) AS AGENT_CODE, MAX(R.PURCHASER_DEPT) AS PO_DEPT_CODE, MAX(H.PURCHASER_ID) AS PO_USER_ID, MAX(R.REQ_DEPT) AS REQ_DEPT_CODE, MAX(R.REQ_USER_ID) AS REQ_USER_ID, MAX(D.CONTRACT_NO) AS CONTRACT_NO, MAX(D.CONTRACT_SEQ) AS CONTRACT_SEQ, MAX(D.BUYER) AS BUYER, MAX((SELECT COUNT(*) FROM ICOMGRDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D' AND AGENT = 'KR00000002')) STOCK_CNT, MAX((SELECT MAX(DS_REMARK) FROM ICOMPORS WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D')) DS_REMARK, MAX(DECODE(D.PROCESS_TYPE,'0' ,(SELECT MIN(INVOICE_DATE) FROM ICOMIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <>'D') ,(SELECT MIN(INV_DATE) FROM WMSIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D'))) AS INVOICE_DATE2, MAX(D.DS_DATE) AS DS_DATE2, MAX(D.SCM_REMARK) AS SCM_REMARK, MAX(D.ADD_DATE) AS ADD_DATE, MAX(R.CANCEL_REMARK) AS CANCEL_REMARK, SUM(G.ITEM_AMT) GR_ITEM_AMT, SUM(G.AGENT_ITEM_AMT) AGENT_GR_ITEM_AMT, MAX((SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = D.BYIT_COMORG_CODE AND BUYER_ITEM_NO = D.BUYER_ITEM_NO)) AS BUYER_CATEGORY_NO, MAX((SELECT H.CATEG_NAME FROM ICOMBYCA H WHERE H.COM_CODE = D.BYIT_COMORG_CODE AND H.STD_CATEG_ID IN (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = D.BYIT_COMORG_CODE AND BUYER_ITEM_NO = D.BUYER_ITEM_NO))) AS BUYER_CATEG_NAME, MAX((SELECT H.CATEG_PATH FROM ICOMBYCA H WHERE H.COM_CODE = D.BYIT_COMORG_CODE AND H.STD_CATEG_ID IN (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = D.BYIT_COMORG_CODE AND BUYER_ITEM_NO = D.BUYER_ITEM_NO))) AS BUYER_CATEG_PATH,
MAX(D.CMS_CATEG_ID) AS CMS_CATEG_ID, MAX((SELECT CATEG_PATH FROM CMSCATEG WHERE CMS_CATEG_ID=D.CMS_CATEG_ID)) AS CATEG_PATH,
MAX((SELECT DECODE(SHIP_ADDRESS_ID,'APKRS001','(유)듀폰 이천공장','APKRSB001','(유)듀폰 울산공장','(유)듀폰') FROM POIFLOAD_DUPO WHERE PO_ORDER_ID = D.LEGACY_PO_NO AND ITEM_LINE_NUMBER = D.LEGACY_PO_SEQ AND ITEM_SUPPLIER_PART_ID = D.BUYER_ITEM_NO)) AS REF_IF_NO,
MAX(D.REF_IF_NO) AS REF_IF_NO,
MAX( D.PO_REMARK ) AS PO_REMARK, MAX((SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = D.PROCESS_TYPE)) AS PROCESS_TEXT, MAX(DECODE(D.PROCESS_TYPE,'1',D.WAREHOUSE_CODE,'3',D.WAREHOUSE_CODE,H.AGENT)) AS ORIGIN_AGENT, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = DECODE(D.PROCESS_TYPE,'1',D.WAREHOUSE_CODE,'3',D.WAREHOUSE_CODE,H.AGENT))) AS ORIGIN_AGENT_NAME, MAX(H.PO_REMARK) AS PO_REMARK_HD, MAX(D.UNIT_TAX) AS UNIT_TAX, MAX(H.DELY_TO_LOCATION) AS LOG_TEXT, (SELECT APPROVAL_RD_DATE from KEP_PO_DELY_MNG WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND SEQ = ( SELECT MAX(SEQ) from KEP_PO_DELY_MNG WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ ) )AS HA_DATE , MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = DECODE(D.PROCESS_TYPE,'2',D.WAREHOUSE_CODE))) AS WAREHOUSE_NAME , MAX(NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE =D.BUYER AND TYPE ='Z014' AND CODE =D.ACCOUNT_TYPE),(SELECT LTEXT FROM COWAY_ACCOUNT_ET_OUTPUT WHERE BGACT = D.ACCOUNT_TYPE AND ROWNUM = 1))) AS ACCOUNT_TYPE , MAX(D.PR_NO) PR_NO , MAX(D.PR_SEQ) PR_SEQ , MAX(R.IMAGE_KEY) IMAGE_KEY , MAX(D.IMAGE_KEY) PO_IMAGE_KEY , MAX(D.ST_DATE) ST_DATE , MAX(D.ITEM_MAKE_TYPE) ITEM_MAKE_TYPE , MAX(H.DOC_TYPE) DOC_TYPE , MAX( DECODE(D.PROCESS_TYPE,'1',(SELECT MAX(SCHEDULED_DATE) FROM WMSIVDT WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS != 'D'),(SELECT MAX(BUYER_DS_DATE) FROM ICOMPORS WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO AND PO_SEQ = D.PO_SEQ AND STATUS <> 'D'))) AS BUYER_DS_DATE , F_GET_RE_SGMNG(MAX(D.BUYER), MAX(D.CMS_CATEG_ID), '',3) AS SOUR_MNG , MAX(R.MAKER_PART_NO) AS MAKER_PART_NO , MAX(D.PLANT) PLANT , MAX(R.EXP_CUR) AS EXP_CUR , MAX(R.EXP_CUR_PRICE) AS EXP_CUR_PRICE , MAX(R.EXP_FOR_UNIT_PRICE) AS EXP_FOR_UNIT_PRICE , MAX(R.EXP_FOR_ITEM_AMT) AS EXP_FOR_ITEM_AMT , MAX(D.ORIGIN_CODE) AS ORIGIN_CODE , MAX(D.CHANGE_USER_DEPT) AS CHANGE_USER_DEPT FROM ICOMPODT D, ICOMGRDT G, ICOMPOHD H, ICOMPRDT R WHERE D.BUYER = H.BUYER
AND D.BUYER IN
#{item}
AND H.BUYER IN
#{item}
AND D.CMS_CATEG_ID IN ( SELECT COD.CODE2 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'SG' AND CODE1 = #{st_kep_user_id} AND FLAG = 'Y' )
AND (D.BUYER, NVL(D.PLANT,'NULL_')) IN ( SELECT COD.TEXT1,COD.TEXT2 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'POMG' AND COD.CODE1 = #{st_plant_user_id} AND COD.FLAG = 'Y' )
AND D.BUYER IN ( SELECT D.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{SessionUserId} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{SessionUserId} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT BUYER FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{SessionUserId} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{SessionUserId} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND D.BUYER = G.BUYER AND D.PO_NO = G.PO_NO AND D.PO_SEQ = G.PO_SEQ AND G.STATUS ^='D'
AND D.BUYER = G.BUYER(+) AND D.PO_NO = G.PO_NO(+) AND D.PO_SEQ = G.PO_SEQ(+) AND G.STATUS(+) ^='D'
AND H.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND G.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND D.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND D.BUYER_ITEM_NO LIKE '%'||UPPER(#{st_buyer_item_no})||'%'
AND D.PO_NO LIKE '%'||UPPER(#{st_po_no})||'%'
AND D.REF_IF_NO LIKE UPPER(#{st_ref_if_no})||'%'
AND D.REF_IF_NO LIKE #{st_if_po_no}||'%'
AND D.LEGACY_PO_NO LIKE #{st_if_po_no}||'%'
AND D.REF_PR_NO LIKE UPPER(#{st_ref_no})||'%'
AND H.DOC_TYPE = #{st_doc_type}
AND D.BUYER_ITEM_NO = UPPER(#{st_buyer_item_no})
AND H.DOC_TYPE = #{st_doc_type}
AND D.PO_NO = UPPER(#{st_po_no})
AND D.REF_IF_NO = UPPER(#{st_ref_if_no})
AND D.REF_IF_NO = #{st_if_po_no}
AND D.LEGACY_PO_NO = #{st_if_po_no}
AND D.REF_PR_NO = UPPER(#{st_ref_no})
AND D.PO_NO = DECODE(NVL((SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = R.BUYER AND PR_NO = R.PR_NO AND PR_SEQ= R.PR_SEQ AND STATUS != 'D'),0),0, (SELECT MAX(PO_NO) FROM ICOMPODT WHERE BUYER=R.BUYER AND PR_NO=R.PR_NO AND PR_SEQ=R.PR_SEQ) , D.PO_NO)
AND G.BUYER IN (#{st_buyer_code})
AND H.AGENT = #{st_agent_code}
AND R.PURCHASER_DEPT = #{st_po_dept_code}
AND R.REQ_DEPT = #{st_req_dept_code}
AND F_GET_PO_STTS(D.BUYER, D.PO_NO , D.PO_SEQ , 0) IN
#{status}
AND D.STATUS <> 'D' AND H.STATUS <> 'D' AND R.STATUS <> 'D' AND 'D' <> G.STATUS(+)
AND D.PLANT LIKE 'E%'
AND D.PO_NO = H.PO_NO AND D.BUYER = R.BUYER AND D.PR_NO = R.PR_NO AND D.PR_SEQ = R.PR_SEQ GROUP BY D.BUYER, D.PO_NO, D.PO_SEQ ORDER BY D.BUYER, D.PO_NO, D.PO_SEQ ) A

mapper.update:

UPDATE ICOMPODT 
	SET IMAGE_KEY    = #{PO_IMAGE_KEY}
	WHERE BUYER = #{BUYER}                                                                   
	AND PO_NO = #{PO_NO}                                                                       
	AND PO_SEQ =  #{PO_SEQ}

