SELECT /* selectMasterMpSoProgressDownLoadList */ DECODE(A.SCM_REMARK,NULL,'','메모') AS SCM_REMARK, A.SCM_REMARK AS SCM_REMARK_TEXT, DECODE( (SELECT COUNT(*) FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ IN ('000000', A.PO_SEQ)), 0, '', (SELECT DECODE(COUNT(*), 0, '11', '10') FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ IN ('000000', A.PO_SEQ) AND STATUS = 'S' AND NOTICE_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD')) ) AS ISSUE_IMG,
A.BUYER_NAME, A.BUYER, DECODE(STOCK_CNT,0,A.STATUS_TEXT,'*'||A.STATUS_TEXT) STATUS_TEXT, A.AGENT_NAME, A.AGENT_CODE, A.PO_NO, A.PO_SEQ, NVL(A.ITEM_QTY,0) AS PO_QTY, DECODE(A.BUYER,'KRDOOS0006',A.REF_IF_NO,A.LEGACY_PO_NO) LEGACY_PO_NO, A.LEGACY_PO_SEQ, A.ADD_DATE, A.PO_DATE, A.PO_DEPT_NAME,
A.PO_USER_NAME, DECODE(#{st_non_masking_flag}, 'Y', A.PO_USER_NAME, F_GET_MASKING_RETURN(A.PO_USER_NAME, 'NAME')) AS PO_USER_NAME_MASK,
A.PO_USER_ID, DECODE(#{st_non_masking_flag}, 'Y', A.PO_USER_ID, F_GET_MASKING_RETURN(A.PO_USER_ID, 'NAME')) AS PO_USER_ID_MASK,
A.BUYER_ITEM_NO, A.DESCRIPTION, A.SPECIFICATION, A.MAKER_NAME, A.UNIT_MEASURE, NVL(A.UNIT_PRICE,0) AS UNIT_PRICE, (NVL(A.ITEM_AMT,0)) AS UNIT_SUM, NVL(A.AGENT_PRICE,0) AS AGENT_PRICE, (NVL(A.AGENT_ITEM_AMT,0)) AS AGENT_SUM, A.REF_PR_NO, A.RD_DATE, A.HA_DATE, A.CD_DATE, A.BUYER_DS_DATE , DECODE(NVL(A.INVOICE_DATE,NULL),NULL,'',A.INVOICE_DATE) INVOICE_DATE, NVL(A.INV_QTY,0) AS INV_QTY, A.DELIVERY_DATE, NVL(A.DELIVERY_QTY,0) AS DELIVERY_QTY, DECODE(NVL(A.GR_DATE,NULL),NULL,'',A.GR_DATE) GR_DATE, NVL(A.GR_QTY,0) AS GR_QTY1, NVL(A.GR_ITEM_AMT,0) AS GR_UNIT_SUM, NVL(A.AGENT_GR_ITEM_AMT,0) AS GR_AGENT_SUM, A.BUYER_CATEGORY_NO AS BUYER_CATEG_ID, A.BUYER_CATEG_NAME AS BUYER_CATEG_NAME, A.BUYER_CATEG_PATH AS BUYER_CATEG_PATH, A.CMS_CATEG_ID AS CMS_CATEG_ID, A.CATEG_PATH AS CATEG_PATH, A.REQ_DEPT_NAME,
A.REQ_USER_NAME, DECODE(#{st_non_masking_flag}, 'Y', A.REQ_USER_NAME, F_GET_MASKING_RETURN(A.REQ_USER_NAME, 'NAME')) AS REQ_USER_NAME_MASK,
A.REQ_USER_ID, DECODE(#{st_non_masking_flag}, 'Y', A.REQ_USER_ID, F_GET_MASKING_RETURN(A.REQ_USER_ID, 'NAME')) AS REQ_USER_ID_MASK,
A.CANCEL_REMARK, A.REF_IF_NO AS REF_IF_NO, A.PO_REMARK AS PO_REMARK, A.PROCESS_TEXT AS PROCESS_TEXT, (SELECT IRS_NO FROM ICOMCMPY WHERE COM_CODE = A.AGENT_CODE) AS AGENT_IRS_NO, A.ORIGIN_AGENT AS ORIGIN_AGENT, A.ORIGIN_AGENT_NAME AS ORIGIN_AGENT_NAME, A.WAREHOUSE_NAME,
